def max_consecutive_answers(answer_key, k):
    def longest_with_flips(target):
        left = 0
        flip_count = 0
        best = 0
        for right, ch in enumerate(answer_key):
            if ch != target:
                flip_count += 1
            while flip_count > k:
                if answer_key[left] != target:
                    flip_count -= 1
                left += 1
            best = max(best, right - left + 1)
        return best

    return max(longest_with_flips('T'), longest_with_flips('F'))

